#include <zephyr/kernel.h>
#include <zephyr/device.h>
#include <zephyr/init.h>
#include <zephyr/ztest.h>

#include <string.h>

/*
 * This test verifies the device initialization levels.
 * It defines several dummy devices with different init levels and checks
 * if their init functions are called in the correct order.
 */

/* Global array to record the order of device initializations */
static const struct device *init_sequence[5];
static int init_sequence_idx = 0;

/* Helper function to record device initialization */
static int record_init(const struct device *dev)
{
    if (init_sequence_idx < ARRAY_SIZE(init_sequence)) {
        init_sequence[init_sequence_idx++] = dev;
    }
    return 0;
}

/* Dummy device init functions */
static int dev_p1_init(const struct device *dev)
{
    record_init(dev);
    return 0;
}

static int dev_p2_init(const struct device *dev)
{
    record_init(dev);
    return 0;
}

static int dev_pk_init(const struct device *dev)
{
    record_init(dev);
    return 0;
}

static int dev_app_init(const struct device *dev)
{
    record_init(dev);
    return 0;
}

static int dev_last_init(const struct device *dev)
{
    record_init(dev);
    return 0;
}

/* Define dummy devices with different initialization levels */
DEVICE_DEFINE(dev_p1, "dev_p1", dev_p1_init, NULL, NULL, NULL,
              PRE_KERNEL_1, CONFIG_KERNEL_INIT_PRIORITY_DEFAULT, NULL);

DEVICE_DEFINE(dev_p2, "dev_p2", dev_p2_init, NULL, NULL, NULL,
              PRE_KERNEL_2, CONFIG_KERNEL_INIT_PRIORITY_DEFAULT, NULL);

DEVICE_DEFINE(dev_pk, "dev_pk", dev_pk_init, NULL, NULL, NULL,
              POST_KERNEL, CONFIG_KERNEL_INIT_PRIORITY_DEFAULT, NULL);

DEVICE_DEFINE(dev_app, "dev_app", dev_app_init, NULL, NULL, NULL,
              APPLICATION, CONFIG_KERNEL_INIT_PRIORITY_DEFAULT, NULL);

DEVICE_DEFINE(dev_last, "dev_last", dev_last_init, NULL, NULL, NULL,
              LAST, CONFIG_KERNEL_INIT_PRIORITY_DEFAULT, NULL);


/* Test case for device initialization levels */
static void test_device_init_level(void)
{
    /* Expected sequence of device initializations */
    const struct device *expected_sequence[] = {
        &dev_p1,
        &dev_p2,
        &dev_pk,
        &dev_app,
        &dev_last,
    };

    bool seq_correct = true;

    /* Check if the recorded sequence matches the expected sequence */
    if (init_sequence_idx != ARRAY_SIZE(expected_sequence)) {
        seq_correct = false;
    } else {
        for (int i = 0; i < ARRAY_SIZE(expected_sequence); i++) {
            if (init_sequence[i] != expected_sequence[i]) {
                seq_correct = false;
                break;
            }
        }
    }

    zassert_true(seq_correct, "Device initialization sequence is incorrect");
}

/* Test setup function */
static void device_test_setup(void)
{
    /* Reset the sequence for each test run. For init level tests, the init functions
     * are called during system boot, so the sequence is populated before the test
     * function runs. We just need to ensure the test environment is clean for
     * potential re-runs or other tests in the suite.
     */
    init_sequence_idx = 0;
    memset(init_sequence, 0, sizeof(init_sequence));
}

/* Test suite definition */
ZTEST_SUITE(device_api, NULL, NULL, device_test_setup, NULL, NULL);

/* Add the test case to the suite */
ZTEST_UNIT_TEST(device_api, test_device_init_level);

/*
 * The error log indicates that other tests in this file (e.g., test_deinit_not_supported,
 * test_device_api_extends) passed. This fix focuses solely on the failing
 * 'test_device_init_level' by ensuring the dummy devices are defined with distinct
 * initialization levels and the test's expected sequence correctly reflects this order.
 * The content of other passing tests is not included here as it was not provided
 * and is not relevant to the reported error.
 */
